window.skillUpFocusedCarryingCapacityQuestions=dedicated([["Symbol for carrying capacity — which option is correct?",["K","N","r","t"],0,"K is the sustainable population limit under the specified environmental conditions."],["Population size symbol — which option is correct?",["K","N","r","t"],1,"N counts individuals, whereas K represents the environmental limit."],["Intrinsic growth rate symbol — which option is correct?",["N","K","r","t"],2,"The intrinsic rate r measures per capita growth without density limitation."],["Logistic curve shape — which option is correct?",["Circular","J-shaped","Linear","S-shaped"],3,"Resource limitation progressively slows growth, producing a sigmoid curve."],["Growth at N=K — which option is correct?",["Zero","rK","K/2","2r"],0,"At N=K the factor 1−N/K equals zero."],["Population size at maximum logistic growth — which option is correct?",["K","K/2","2K","K/4"],1,"The quadratic rN(1−N/K) reaches its maximum at half K."],["Growth when N exceeds K and r is positive — which option is correct?",["Zero","Positive","Negative","Infinite"],2,"Above K the density factor is negative, so population size falls."],["Growth when N is much smaller than K — which option is correct?",["Instant equilibrium","Always zero","Always negative","Approximately exponential"],3,"When N/K is small the density factor approaches one."],["Logistic density factor — which option is correct?",["1 − N/K","N/K","K/N","1 + N/K"],0,"The factor declines from near one to zero as N approaches K."],["Per capita logistic growth — which option is correct?",["rN","r(1 − N/K)","rK","K/N"],1,"Dividing total logistic growth by N yields the per capita rate."],["Maximum growth when K=800 occurs at N — which option is correct?",["200","800","400","1600"],2,"Half of 800 is 400, where total growth peaks."],["Density factor when N=100 and K=400 — which option is correct?",["0","0.25","4","0.75"],3,"Subtract 100/400 from one to obtain 0.75."],["Density factor when N=300 and K=600 — which option is correct?",["0.5","2","0","1.5"],0,"Subtract 300/600 from one to obtain 0.5."],["Growth when r=0.2, N=100, K=200 — which option is correct?",["20","10","40","0"],1,"Multiply 0.2 × 100 × (1−100/200) to obtain 10."],["Growth when r=0.1, N=600, K=300 — which option is correct?",["30","60","−60","0"],2,"Multiply 0.1 × 600 × (1−600/300) to obtain −60."],["Resource loss effect on K — which option is correct?",["Makes K infinite","Always doubles K","Never changes K","May decrease K"],3,"Loss of resources reduces the number of individuals the habitat can support."],["Improved limiting nutrient availability — which option is correct?",["May increase K","Always reduces K","Eliminates reproduction","Makes N zero"],0,"Relieving nutrient limitation may increase sustainable population size."],["Seasonal change in K — which option is correct?",["Impossible","Possible","Only in bacteria","Only in oceans"],1,"Seasonal changes in food, water and habitat can alter K."],["Density-dependent factor — which option is correct?",["Radioactive decay","Earth rotation","Competition for food","Day length alone"],2,"Competition for finite food generally intensifies with population density."],["Population overshoot — which option is correct?",["K equals r","N always zero","N always below K","N temporarily exceeds K"],3,"Overshoot occurs when population size temporarily exceeds sustainable capacity."],["Possible overshoot consequence — which option is correct?",["Resource depletion","Unlimited resources","No mortality","No competition"],0,"Excess consumption can exhaust resources and increase mortality."],["Model without resource limitation — which option is correct?",["Logistic with finite K","Exponential","Declining linear","Constant zero"],1,"Exponential growth assumes no density-dependent resource constraint."],["Per capita growth at N=K/2 — which option is correct?",["0","rK","r/2","2r"],2,"At N=K/2 the density factor is one half."],["Births and deaths at closed population equilibrium — which option is correct?",["Deaths always exceed births","Both necessarily zero","Births always exceed deaths","Balance"],3,"In a closed population, equal births and deaths produce zero net growth."],["Species-specific K in one habitat — which option is correct?",["Can differ","Always identical","Always zero","Always infinite"],0,"Different species have different resource requirements and tolerances."],["Habitat quality effect — which option is correct?",["Never matters","Can alter K","Only changes DNA","Eliminates competition"],1,"Habitat quality affects the supply of limiting resources."],["Strongest logistic limitation below K — which option is correct?",["At N=0","Near zero","Near K","At K/1000"],2,"Near K, the density factor approaches zero and growth is strongly limited."],["Basic logistic model parameters — which option is correct?",["No reproduction","Infinite K required","Zero r required","Constant r and K"],3,"The simplest logistic equation treats r and K as fixed parameters."],["Environmental resistance — which option is correct?",["Factors limiting growth","Unlimited food","Only mutation","Only immigration"],0,"Environmental resistance includes resource scarcity and other growth constraints."],["Carrying capacity definition — which option is correct?",["Maximum individual age","Sustainable population under given conditions","Species count","Maximum birth rate"],1,"Carrying capacity is the population that can be sustained under given conditions."]]);

